import { registerWebComponents } from '@domg-wc/common';
import { VlRichDataField, VlRichDataTable } from '@domg-wc/components/block';

registerWebComponents([VlRichDataTable, VlRichDataField]);

// Statische data mag als JSON in het attribuut data. Wijzigt de data in de browser, zet dan de property:
// document.querySelector('vl-rich-data-table').data = { data: [...] };

import { registerWebComponents } from '@domg-wc/common';
import { VlRichDataField, VlRichDataTable } from '@domg-wc/components/block';

registerWebComponents([VlRichDataTable, VlRichDataField]);

// vl-rich-data-table sorteert niet zelf. Een klik op de kop van een veld met sortable wisselt de richting (oplopend,
// aflopend, geen) en geeft het event change, met in event.detail.sorting de actieve sorteringen
// ({ name, direction, priority }) of null. name is de name van het vl-rich-data-field, hier ook de sleutel in de data.
const tableSorter = (table) => {
    const originalTableData = [...table.data.data];
    return (event) => {
        const { sorting } = event.detail;
        const table = event.target;
        if (sorting) {
            table.data = {
                data: [...originalTableData].sort((firstEl, secondEl) => {
                    for (let i = 0; i < sorting.length; i++) {
                        const criteria = sorting[i];
                        const firstValue = firstEl[criteria.name];
                        const secondValue = secondEl[criteria.name];
                        const isAscending = criteria.direction === 'asc';
                        if (firstValue < secondValue) {
                            return isAscending ? -1 : 1;
                        } else if (firstValue > secondValue) {
                            return isAscending ? 1 : -1;
                        }
                    }
                    return 0;
                }),
                sorting,
            };
        } else {
            // Geen sortering meer: de oorspronkelijke volgorde. Zet een object met data; de code op de pagina zet
            // hier de array zelf, en dan toont de tabel 'Er werden geen resultaten gevonden'.
            table.data = { data: originalTableData };
        }
    };
};

customElements.whenDefined('vl-rich-data-table').then(() => {
    const table = document.querySelector('#rich-data-table-sorting');
    if (table) table.addEventListener('change', tableSorter(table));
});

