// vl-rich-data-table filtert niet zelf. Bij elke invoer in een veld van de filter en bij een reset volgt het event
// change; event.detail.formData bevat de velden van het formulier, of is undefined als ze allemaal leeg zijn. De name
// van elk veld is het pad in de data, bv. manager.lastName.
customElements.whenDefined('vl-rich-data-table').then(() => {
    const element = document.querySelector('#rich-data-table-filter');
    if (element) {
        element.data = data;
        element.addEventListener('change', (e) => {
            let filteredData = [...data.data];
            if (e.detail.formData) {
                for (const entry of e.detail.formData.entries()) {
                    filteredData = filter(filteredData, entry[0], entry[1]);
                }
            }
            // paging.totalItems zet total-items op vl-pager en het aantal resultaten boven de tabel.
            element.data = {
                data: filteredData,
                paging: {
                    currentPage: 1,
                    totalItems: filteredData.length,
                },
            };
        });
        const filter = (data, pathToKey, value) => {
            if (value === '') {
                return data;
            } else {
                return data.filter((element) => {
                    const valueByPath = findValueByPath(element, pathToKey);
                    return valueByPath.includes(value);
                });
            }
        };
        const findValueByPath = (element, pathToKey) => {
            const keys = pathToKey.split('.');
            let current = element;
            for (let i = 0; i < keys.length; i++) {
                if (current[keys[i]] !== undefined) {
                    current = current[keys[i]];
                } else {
                    return undefined;
                }
            }
            return current.toString();
        };
    }
});

