// change volgt bij een wijziging in de filter en bij een andere pagina in vl-pager. event.detail.paging bevat de
// huidige pagina; na een wijziging in de filter is currentPage 1. Filter en pagineer de data zelf.
customElements.whenDefined('vl-rich-data-table').then(() => {
    const data = richDataFilterPagerData;
    const richTable = document.querySelector('#rich-data-table-pagination');
    const pager = document.querySelector('#pager-for-rich-data-table');
    if (richTable && pager) {
        richTable.addEventListener('change', (e) => {
            let newData = data.data;
            let totalItems = data.data.length;
            let filterEntries = undefined;
            if (e.detail.formData) {
                filterEntries = [];
                for (const entry of e.detail.formData.entries()) {
                    newData = filter(newData, entry[0], entry[1]);
                    totalItems = newData.length;
                    filterEntries.push({
                        name: entry[0],
                        value: entry[1],
                    });
                }
            }
            if (e.detail.paging) {
                newData = page(e.detail.paging.currentPage, pager.itemsPerPage, newData);
            }
            // paging zet current-page en total-items op vl-pager; filter zet de waarden in de velden van de filter.
            richTable.data = {
                data: newData,
                paging: {
                    currentPage: e.detail.paging.currentPage,
                    totalItems: totalItems,
                },
                filter: filterEntries,
            };
        });
        const page = (page, itemsPerPage, data) => {
            const start = (page - 1) * itemsPerPage;
            const end = start + itemsPerPage;
            return data.slice(start, end);
        };
        richTable.data = {
            data: page(1, 10, data.data),
        };
        const filter = (data, pathToKey, value) => {
            if (value === '') {
                return data;
            }
            return data.filter((element) => {
                const valueByPath = findValueByPath(element, pathToKey);
                return valueByPath.includes(value);
            });
        };
        const findValueByPath = (element, pathToKey) => {
            const keys = pathToKey.split('.');
            let current = element;
            for (let i = 0; i < keys.length; i++) {
                if (current[keys[i]] !== undefined) {
                    current = current[keys[i]];
                } else {
                    return undefined;
                }
            }
            return current.toString();
        };
    }
});

import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlRichDataField, VlRichDataTable } from '@domg-wc/components/block';
import { VlCheckboxComponent } from '@domg-wc/components/form';
import { vlAccessibilityStyles } from '@domg-wc/styles';

registerWebComponents([VlRichDataTable, VlRichDataField, VlButtonComponent, VlTitleComponent, VlCheckboxComponent]);

// De code van de pagina, zonder types. Anders dan op de pagina geeft ze ook getSelection terug.
const selectableRichTableImplementation = () => {
    const headerCheckbox = document.createElement('vl-checkbox');
    headerCheckbox.setAttribute('label', 'Selecteer alles');

    const getHeaderCheckboxInput = () => headerCheckbox.shadowRoot.querySelector('input');

    const getTable = () => document.querySelector('#rich-data-table-selectable');

    const getTableData = () => getTable()?.data.data || [];

    // Zet checked en indeterminate op de checkbox in de kop volgens de selectie van de rijen.
    const syncHeaderCheckbox = () => {
        const tableData = getTableData();
        const allSelected = tableData.length > 0 && tableData.every((item) => item.selected);
        const noneSelected = tableData.every((item) => !item.selected);

        headerCheckbox.toggleAttribute('indeterminate', !allSelected && !noneSelected);
        headerCheckbox.toggleAttribute('checked', allSelected);
    };

    const applySelectionToAllRows = (selected) => {
        headerCheckbox.removeAttribute('indeterminate');
        const table = getTable();
        if (!table) return;
        const tableData = getTableData();
        table.data = { ...table.data, data: [...tableData.map((item) => ({ ...item, selected }))] };
    };

    const handleSelectAllToggle = (e) => {
        const {
            detail: { checked },
        } = e;
        applySelectionToAllRows(checked);
    };

    const getSelection = () => getTableData().filter((item) => item.selected);

    const checkActions = () => {
        const selection = getSelection();
        const selectionCount = selection.length;
        const hasSelection = selectionCount > 0;

        document.querySelector('#default-actions')?.toggleAttribute('hidden', hasSelection);
        document.querySelector('#selection-actions')?.toggleAttribute('hidden', !hasSelection);

        const removeSelectionButton = document.querySelector('#remove-selection');
        const selectionStatus = document.querySelector('#selection-status');

        if (removeSelectionButton && selectionStatus) {
            const selectionText = `${selectionCount} item${selectionCount !== 1 ? 's' : ''} geselecteerd`;
            selectionStatus.innerText = selectionText;
            removeSelectionButton.innerText = selectionText;
            return;
        }

        if (!hasSelection && headerCheckbox) {
            getHeaderCheckboxInput()?.focus();
            return;
        }
    };

    const dataFieldRenderer = (td, { selected, name: rowName }) => {
        const checkbox = document.createElement('vl-checkbox');
        checkbox.setAttribute('label', `Selecteer ${rowName}`);
        checkbox.toggleAttribute('checked', selected);
        checkbox.addEventListener('vl-change', (e) => {
            const {
                detail: { checked },
            } = e;

            const tableData = getTableData();
            const rowData = tableData.find(({ name }) => name === rowName);
            if (rowData) rowData.selected = checked;

            syncHeaderCheckbox();
        });
        td.appendChild(checkbox);
    };

    const headerTemplate = () => {
        const td = document.createElement('td');
        const headerLabel = document.createElement('span');
        headerLabel.setAttribute('class', 'vl-visually-hidden');
        headerLabel.innerText = 'Maak selectie';
        td.innerHTML = `<style>${vlAccessibilityStyles}</style>`;
        td.appendChild(headerLabel);
        td.appendChild(headerCheckbox);
        requestAnimationFrame(() => {
            // vl-input volgt enkel op een klik van de gebruiker, niet als syncHeaderCheckbox checked zet.
            headerCheckbox.addEventListener('vl-input', handleSelectAllToggle);
            syncHeaderCheckbox();
        });
        return td;
    };

    return {
        checkActions,
        headerTemplate,
        dataFieldRenderer,
        applySelectionToAllRows,
        getSelection,
    };
};

customElements.whenDefined('vl-rich-data-table').then(() => {
    const table = document.querySelector('#rich-data-table-selectable');
    const { checkActions, headerTemplate, dataFieldRenderer, applySelectionToAllRows, getSelection } =
        selectableRichTableImplementation();

    // renderer (vult de cel van elke rij) en headerTemplate (geeft de cel van de kop) zijn properties van
    // vl-rich-data-field, geen attributen. Maak het veld daarom in code en voeg het als eerste kolom toe: bij een nieuw
    // veld tekent de tabel de kop en de rijen opnieuw.
    const selectionField = document.createElement('vl-rich-data-field');
    selectionField.renderer = dataFieldRenderer;
    selectionField.headerTemplate = headerTemplate;
    table.prepend(selectionField);

    // De checkboxen staan in de tabel; hun vl-change bubbelt (composed) tot bij vl-rich-data-table.
    table.addEventListener('vl-change', () => checkActions());

    const onClick = (selector, handler) => document.querySelector(selector).addEventListener('vl-click', handler);
    onClick('#add-folder', () => console.log('add folder'));
    onClick('#add-document', () => console.log('add document'));
    onClick('#remove-selection', () => applySelectionToAllRows(false));
    onClick('#selection-actions vl-button[icon="move-left-right"]', () => console.log('move selection', getSelection()));
    onClick('#selection-actions vl-button[icon="data-download"]', () => console.log('download selection', getSelection()));
    onClick('#selection-actions vl-button[icon="trash"]', () => console.log('delete selection', getSelection()));
});
